const highlandSoldierSheet=new Image();highlandSoldierSheet.assetSrc='assets/highland-soldier-v1.png';
function beginHighlandSoldier(e){let angle=Math.atan2(p.y-e.y,p.x-e.x);e.state='attack';e.elapsed=0;e.struck=false;e.facing=Math.cos(angle)-Math.sin(angle)<0?-1:1;e.attack={pattern:'highlandTurnCombo',bespoke:true,windup:.9,angle,origin:{x:e.x,y:e.y},swept:false,thrustAngle:null,reach:0,thrust:false};}
function highlandSoldierContains(a,point,thrust=false){let dx=point.x-a.origin.x,dy=point.y-a.origin.y,angle=thrust?a.thrustAngle:a.angle;if(angle===null)return false;if(thrust){let along=dx*Math.cos(angle)+dy*Math.sin(angle),side=-dx*Math.sin(angle)+dy*Math.cos(angle);return a.reach>0&&along>=-1e-8&&along<=a.reach+1e-8&&Math.abs(side)<=24+1e-8;}let delta=Math.atan2(dy,dx)-angle;delta=Math.atan2(Math.sin(delta),Math.cos(delta));return Math.hypot(dx,dy)<=135+1e-8&&Math.abs(delta)<=Math.PI*7/18+1e-8;}
function lockHighlandThrust(e,a){a.thrustAngle=Math.atan2(p.y-e.y,p.x-e.x);a.windup=2.05;e.struck=false;for(let r=10;r<=270;r+=10){if(!lineClear(a.origin,{x:e.x+Math.cos(a.thrustAngle)*r,y:e.y+Math.sin(a.thrustAngle)*r}))break;a.reach=r;}e.facing=Math.cos(a.thrustAngle)-Math.sin(a.thrustAngle)<0?-1:1;}
const highlandSoldierAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r6e2')return highlandSoldierAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='highlandTurnCombo'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=180&&clear){beginHighlandSoldier(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.65;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,94*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,17)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.4;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.swept&&e.elapsed>=.9){a.swept=true;e.struck=true;if(highlandSoldierContains(a,p)&&lineClear(a.origin,p))hurt(48);playSound('slash',e.x,e.y);}
 if(a.thrustAngle===null&&e.elapsed>=1.25)lockHighlandThrust(e,a);
 if(!a.thrust&&e.elapsed>=2.05){a.thrust=true;e.struck=true;if(highlandSoldierContains(a,p,true)&&lineClear(a.origin,p))hurt(74);playSound('slash',e.x,e.y);}
 if(e.elapsed>=2.9){e.attack=null;e.state='idle';e.t=1.8;}
};
const highlandSoldierDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r6e2'||!highlandSoldierSheet.complete||!highlandSoldierSheet.naturalWidth||!highlandSoldierSheet.naturalHeight)return highlandSoldierDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:0,col:0};else if(e.attack?.pattern==='highlandTurnCombo')f={row:2,col:e.elapsed<.9?0:e.elapsed<1.25?1:e.elapsed<2.05?2:3};let q=project(e.x,e.y),sw=highlandSoldierSheet.naturalWidth/4,sh=highlandSoldierSheet.naturalHeight/3,w=240,h=w*sh/sw,anchor=.92;ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,highlandSoldierSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(highlandSoldierSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const highlandSoldierSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r6e2'?145:highlandSoldierSizeBase(e);
const highlandSoldierGroundBase=drawGroundEffects;drawGroundEffects=()=>{highlandSoldierGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r6e2'):enemies)){let a=e.attack;if(e.species!=='r6e2'||e.hp<=0||a?.pattern!=='highlandTurnCombo'||!visibleAt(e.x,e.y)||e.elapsed>=2.25)continue;let thrust=a.thrustAngle!==null,fired=thrust?a.thrust:a.swept;if(!thrust&&e.elapsed>=1.1)continue;ctx.save();ctx.strokeStyle=fired?'#fff4cb':thrust?'#d5a3f0':'#dfb56a';ctx.fillStyle=thrust?'#b07bd92a':'#d4a65326';ctx.lineWidth=fired?3:2;ctx.beginPath();if(thrust){if(a.reach<=0){ctx.restore();continue;}let c=Math.cos(a.thrustAngle),s=Math.sin(a.thrustAngle);for(let [i,[along,side]]of [[0,-24],[a.reach,-24],[a.reach,24],[0,24]].entries()){let q=project(a.origin.x+c*along-s*side,a.origin.y+s*along+c*side);if(i)ctx.lineTo(q.x,q.y);else ctx.moveTo(q.x,q.y);}ctx.closePath();}else{let q=project(a.origin.x,a.origin.y);ctx.translate(q.x,q.y);ctx.transform(ISOX,ISOY,-ISOX,ISOY,0,0);ctx.moveTo(0,0);ctx.arc(0,0,135,a.angle-Math.PI*7/18,a.angle+Math.PI*7/18);ctx.closePath();}ctx.fill();ctx.stroke();ctx.restore();}};
